const fruits = ["apple", "orange", "mango", "grapes"];
console.log(fruits.push("guava"), fruits);
console.log(fruits.pop(), fruits);
console.log(fruits.unshift("kiwi"), fruits);
console.log(fruits.shift(), fruits);

const months = ["Jan", "march", "April", "June", "July"];
months.splice(months.length, 0, "Dec");      // add at end
months.splice(months.indexOf("march"), 1, "March"); // replace
const removed = months.splice(months.indexOf("June"), 1); // delete
console.log(months, removed);

console.log(months.slice(1, 3), months.at(-1));

const numbers = [1, 2, 3, 4, 5];

const ret = numbers.forEach((n) => n * 2);
console.log("forEach returns:", ret);

const doubled = numbers.map((n) => n * 2);
console.log("map returns:", doubled, "original:", numbers);

const words = ["APPLE", "banana", "Cherry"];
console.log(words.map((w) => w.toLowerCase()));
console.log(["ram", "vinod"].map((n) => `Mr. ${n}`));

const evenSquares = numbers.filter((n) => n % 2 === 0).map((n) => n * n);
console.log(evenSquares);

const products = [
  { name: "Laptop", price: 1200 },
  { name: "Phone", price: 800 },
  { name: "Tablet", price: 300 },
  { name: "Smartwatch", price: 150 },
];
console.log(products.filter((p) => p.price <= 500));
console.log(products.find((p) => p.price > 700));
console.log(products.findIndex((p) => p.name === "Tablet"));
console.log(products.some((p) => p.price > 1000), products.every((p) => p.price > 200));

const nums = [1, 2, 3, 4, 6, 5, 6, 7];
console.log(nums.indexOf(6), nums.lastIndexOf(6), nums.includes(9));
console.log(nums.filter((v, i, a) => a.indexOf(v) === i));
console.log([...new Set(nums)]);
console.log([NaN].indexOf(NaN), [NaN].includes(NaN));

const nums = [10, 9, 1, 100, 25];
console.log([...nums].sort());
console.log([...nums].sort((a, b) => a - b));
console.log([...nums].sort((a, b) => b - a));

const names = ["éclair", "Banana", "apple", "Cherry"];
console.log([...names].sort());
console.log([...names].sort((a, b) => a.localeCompare(b)));

const users = [
  { name: "Asha", age: 31 },
  { name: "Ravi", age: 22 },
  { name: "Meera", age: 27 },
];
console.log(users.toSorted((a, b) => a.age - b.age).map((u) => u.name));
console.log(users.map((u) => u.name));

const prices = [100, 200, 300, 400, 500];
const total = prices.reduce((acc, p) => acc + p, 0);
console.log("total:", total);

const fruits = ["apple", "mango", "apple", "banana", "mango", "apple"];
const count = fruits.reduce((acc, f) => {
  acc[f] = (acc[f] || 0) + 1;
  return acc;
}, {});
console.log(count);

const people = [
  { name: "A", city: "Pune" },
  { name: "B", city: "Delhi" },
  { name: "C", city: "Pune" },
];
const byCity = people.reduce((acc, p) => {
  (acc[p.city] ||= []).push(p.name);
  return acc;
}, {});
console.log(byCity);

console.log(Math.max(...prices), prices.reduce((a, b) => Math.max(a, b)));

console.log([1, [2, [3, [4]]], 5].flat());
console.log([1, [2, [3, [4]]], 5].flat(Infinity));

