const nums = [1, 2, 3, 4, 5, 6, 4];
console.log(nums.findLast((n) => n > 4), nums.findLastIndex((n) => n === 4));

const chunk = (arr, n) =>
  Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
console.log(chunk([1, 2, 3, 4, 5, 6, 7], 3));

